const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
async function renderProducts(){
 try{const r=await fetch('/api/offers',{credentials:'same-origin'});if(!r.ok)throw new Error('Connexion utilisateur requise');const d=await r.json();const html=d.offers.map(o=>{const pending=!o.published;const pct=Math.round((Number(o.display_value_cfa)/Number(o.min_amount_cfa)-1)*100);return `<article class="product ${pending?'product-pending':''}">${o.image_url?`<img class="product-image" src="${escapeIA(o.image_url)}" alt="${escapeIA(o.name)}" loading="lazy">`:'<div class="product-art">S</div>'}<div><h3>${escapeIA(o.name)}</h3>${pending?'<span class="product-pending-tag">En attente de mise en ligne</span>':''}<p>${escapeIA(cleanUserOfferDescription(o.description))}</p><p>Période : ${escapeIA(o.duration_label)}</p><p>Montant : ${Number(o.min_amount_cfa).toLocaleString('fr-FR')} FCFA</p><p>Taux affiché : ${pct}%</p><p>Revenu prévu : ${Math.max(0,Number(o.display_value_cfa)-Number(o.min_amount_cfa)).toLocaleString('fr-FR')} FCFA</p><p>Montant total à recevoir : ${Number(o.display_value_cfa).toLocaleString('fr-FR')} FCFA</p>${pending?'<button class="pending-product-button" type="button" data-pending-product aria-disabled="true">Pas encore en ligne</button>':`<p class="quota-count">Limite personnelle : <strong>${Number(o.remaining)||0}</strong> / ${Number(o.total_limit)||0}</p><button class="primary" data-invest-offer="${Number(o.id)}" ${o.remaining<=0||(o.stock_limit!==null&&Number(o.stock_used)>=Number(o.stock_limit))?'disabled':''}>${o.remaining<=0?'Limite atteinte':'Investir'}</button>`}</div></article>`}).join('');$('#all-products').innerHTML=html;$('#home-products').innerHTML=d.offers.slice(0,1).map(o=>`<article class="product">${o.image_url?`<img class="product-image" src="${o.image_url}" alt="${o.name}" loading="lazy">`:'<div class="product-art">S</div>'}<div><h3>${o.name}</h3><p>Limite personnelle : <strong>${o.remaining}</strong> / ${o.total_limit}</p><p>Stock : <strong>${o.stock_limit===null?'Illimité':Math.max(0,Number(o.stock_limit)-Number(o.stock_used))+' / '+o.stock_limit}</strong></p><button class="primary" data-invest-offer="${o.id}" ${o.remaining<=0||(o.stock_limit!==null&&Number(o.stock_used)>=Number(o.stock_limit))?'disabled':''}>${o.remaining<=0?'Limite atteinte':'Investir'}</button></div></article>`).join('');
 }catch(e){const message=escapeIA(e.message||'Impossible de charger les offres.');$('#all-products').innerHTML=`<article class="panel"><p class="muted">${message}</p></article>`;$('#home-products').innerHTML=`<article class="panel"><p class="muted">${message}</p></article>`}
}
