function renderVIP(){const host=$('#vip-levels');if(!host)return;host.innerHTML=SMILE_VIP_LEVELS.map(v=>{const teamLevels=v.teamLevels||'niveaux 1, 2 et 3';const directLine=v.directVip?`<p>Membres VIP1+ directs requis : <strong>${v.directVip}</strong></p>`:'';const salaryTitle=v.level===1?'Stage annoncé (7 jours)':'Rémunération mensuelle annoncée';const salaryValue=v.salary===undefined?'À examiner':(v.salary===null?'Stage de 7 jours':vipMoney(v.salary));const salaryFrequency=v.level===1?'Durée : 7 jours':(v.salaryLabel||'Versement hebdomadaire');const reviewNote=v.level<=4?'<small class="vip-review-note">Annonce à examiner — non activée, aucun crédit automatique.</small>':'';return `<article class="vip-level-card vip-level-${v.level}"><div class="vip-card-head"><span class="vip-crown">👑</span><div><small>PROGRAMME SMILE</small><h3>VIP ${v.level}</h3></div><span class="vip-status">Objectif à atteindre</span></div><div class="vip-stats"><div><small>Niveau</small><strong>VIP ${v.level}</strong></div><div><small>Nombre de subordonnés</small><strong>0</strong></div><div><small>Recharge des subordonnés</small><strong>0 FCFA</strong></div><div><small>Subordonnés directs</small><strong>0</strong></div><div><small>Recharge personnelle</small><strong>0 FCFA</strong></div></div><div class="vip-goals"><h4>Conditions d’accès</h4><p>Recharge personnelle : <strong>${vipMoney(v.personal)}</strong></p><p>Clients de l’équipe (${teamLevels}) : <strong>${v.clients.toLocaleString('fr-FR')}</strong></p><p>Recharge totale des subordonnés (${teamLevels}) : <strong>${v.team===null?'Seuil à confirmer':vipMoney(v.team)}</strong></p>${directLine}<div class="vip-salary"><span>${salaryTitle}</span><strong>${salaryValue}</strong><small>${vipMoney(v.daily)} / jour · ${salaryFrequency}</small>${reviewNote}</div><p class="vip-benefit-count">${v.benefits} avantages annoncés — détails à confirmer dans le référentiel officiel.</p><button type="button" class="vip-locked" disabled>Objectif non atteint</button></div></article>`}).join('');const current=$('#vip-current-level');if(current)current.textContent='À déterminer';}
let iaCategory='ia';
let iaOffers=[];
function offerCategory(o){const allowed=['ia','super','limited','daily','team'];return allowed.includes(o.category)?o.category:'ia'}
function renderIAProducts(){
 const host=$('#ia-products');if(!host)return;
 const list=iaOffers.filter(o=>offerCategory(o)===iaCategory).sort((a,b)=>{if(iaCategory!=='super')return 0;const av=/^SMILE\s+VIP\s*1\.0$/i.test(String(a.name||'')),bv=/^SMILE\s+VIP\s*1\.0$/i.test(String(b.name||''));return av===bv?0:(av?-1:1)});
 if(!list.length){host.innerHTML='<article class="panel ia-empty"><div class="ia-empty-art">✦</div><h3>Bientôt disponible</h3><p class="muted">Aucune offre publiée dans cette catégorie pour le moment.</p></article>';return}
 host.innerHTML=list.map(o=>{
  const sold=Number(o.stock_used)||0,stock=o.stock_limit===null?null:Math.max(0,Number(o.stock_limit)-sold),pending=!o.published,scheduled=o.category==='limited'&&o.limited_status==='scheduled',hidden=o.purchase_enabled===false,closed=hidden||scheduled||Number(o.remaining)<=0||(stock!==null&&stock<=0),pct=Math.round((Number(o.display_value_cfa)/Number(o.min_amount_cfa)-1)*100);
  const isLimited=o.category==='limited';
  const topTarget=isLimited?o.sale_end_at:null,topLabel='Fin de l’offre dans';
  const topTimer=isLimited&&topTarget?`<div class="limited-topbar"><strong>◷ Offre à temps limité</strong><span>⌛ ${topLabel} <b data-limited-countdown="${escapeIA(topTarget)}">Calcul…</b></span></div>`:'';
  // Le compteur de lancement reste visible après le démarrage et se fige à zéro.
  const beforeLaunchTimer=isLimited?`<div class="limited-countdown"><strong>⌛ Compte à rebours avant la mise en ligne :</strong><span data-limited-countdown="${escapeIA(o.sale_start_at||'')}">00:00:00:00</span></div>`:'';
  const imageSrc=o.image_url|| (isLimited?'/smile-limited-banner.png':'');
  const reservation=isLimited?`<p>Réservations restantes : <strong>${Number(o.reservations_remaining)||0}</strong></p>`:'';
  const limitedDetails=isLimited?`<p>Limite d’achat : <strong>${Number(o.total_limit)||0}</strong></p><p>Stock : <strong>${stock===null?'Illimité':stock+' restant(s)'}</strong></p>`:'';
  const actionHtml=pending?'<button class="pending-product-button" type="button" data-pending-product aria-disabled="true">Pas encore en ligne</button>':(scheduled?`<button class="primary limited-action" data-invest-offer="${Number(o.id)}">Réserver</button>`:(hidden?'<button class="pending-product-button" type="button" disabled>Bientôt disponible</button>':`<p class="quota-count">Limite personnelle restante : <strong>${Number(o.remaining)||0}</strong> / ${Number(o.total_limit)||0}</p><button class="primary ${isLimited?'limited-action':''}" data-invest-offer="${Number(o.id)}" ${closed||(isLimited&&Number(o.reservations_remaining)<=0)?'disabled':''}>${closed?'Indisponible':(isLimited?'Souscrire maintenant':'Souscrire')}</button>`));
  const infoHtml=`<span class="ia-tag">${iaLabel(iaCategory)}</span><h3>${escapeIA(o.name)}</h3>${pending?'<span class="product-pending-tag">En attente de mise en ligne</span>':(scheduled?'<span class="product-pending-tag">Ouverture programmée</span>':(hidden?'<span class="product-pending-tag">Bientôt disponible</span>':''))}<p>${escapeIA(cleanUserOfferDescription(o.description||'Offre SMILE'))}</p><p>Durée : <strong>${escapeIA(o.duration_label||'—')}</strong></p><p>Montant : <strong>${Number(o.min_amount_cfa).toLocaleString('fr-FR')} FCFA</strong></p><p>Profit attendu : <strong>${Math.max(0,Number(o.display_value_cfa)-Number(o.min_amount_cfa)).toLocaleString('fr-FR')} FCFA</strong></p>${!isLimited?`<p>Taux : <strong>${pct}%</strong></p><p>Montant total prévu : <strong>${Number(o.display_value_cfa).toLocaleString('fr-FR')} FCFA</strong></p>`:''}${limitedDetails}${reservation}`;
  if(isLimited){
   return `<article class="product ia-product limited-product-card ${pending?'product-pending':''}">${topTimer}<div class="limited-product-body">${imageSrc?`<img class="product-image limited-product-image" src="${escapeIA(imageSrc)}" alt="${escapeIA(o.name)}" loading="lazy">`:'<div class="product-art ia-art">✦</div>'}<div class="limited-product-info">${infoHtml}</div></div>${beforeLaunchTimer}<div class="limited-product-action">${actionHtml}</div></article>`;
  }
  return `<article class="product ia-product ${pending?'product-pending':''}">${imageSrc?`<img class="product-image" src="${escapeIA(imageSrc)}" alt="${escapeIA(o.name)}" loading="lazy">`:'<div class="product-art ia-art">✦</div>'}<div>${infoHtml}${actionHtml}</div></article>`;
 }).join('');updateLimitedCountdowns();
}
function updateLimitedCountdowns(){document.querySelectorAll('[data-limited-countdown]').forEach(el=>{const raw=el.dataset.limitedCountdown,target=raw?new Date(raw).getTime():NaN,left=Number.isFinite(target)?Math.max(0,target-Date.now()):0,days=Math.floor(left/86400000),hours=Math.floor(left%86400000/3600000),minutes=Math.floor(left%3600000/60000),seconds=Math.floor(left%60000/1000),value=left<=0?'00:00:00:00':`${String(days).padStart(2,'0')}:${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;el.textContent=value})}
if(!window.smileLimitedCountdownTimer)window.smileLimitedCountdownTimer=setInterval(updateLimitedCountdowns,1000);
function cleanUserOfferDescription(value){return String(value??'').replace(/\s*[—–-]?\s*illustration dorée personnalisable depuis l’administration\.?/ig,'').replace(/Offre SMILE Temps Limité\s*[—–-]?\s*brouillon à programmer et vérifier avant publication\.?/ig,'').replace(/Profit attendu indicatif,?\s*non garanti\.?/ig,'').replace(/brouillon à programmer et vérifier avant publication\.?/ig,'').trim()}
function escapeIA(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function iaLabel(cat){return ({ia:'CRYPTO',super:'SUPER CRYPTO',limited:'SM Durée limitée',daily:'Revenu quotidien',team:'Produit d’équipe'})[cat]||'CRYPTO'}
async function loadIAProducts(){const host=$('#ia-products');if(!host)return;try{const r=await fetch('/api/offers',{credentials:'same-origin'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Connexion requise');iaOffers=d.offers||[];renderIAProducts()}catch(e){host.innerHTML=`<article class="panel"><p class="muted">${escapeIA(e.message||'Impossible de charger les offres.')}</p></article>`}}
document.addEventListener('click',e=>{const pending=e.target.closest('[data-pending-product]');if(pending){toast('Ce produit n’est pas encore en ligne. Veuillez patienter jusqu’à son activation.');return}const b=e.target.closest('[data-ia-category]');if(!b)return;iaCategory=b.dataset.iaCategory;document.querySelectorAll('[data-ia-category]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active))});renderIAProducts()});
function toast(t){const e=$("#toast");e.textContent=t;e.style.display="block";setTimeout(()=>e.style.display="none",2600)}
const smileTabStack=[];let smileCurrentTab='home';
const smilePageTitles={rewards:'CRYPTO',products:'Produits',team:'Gestion d’équipe',publications:'Actualités SMILE',account:'Mon compte',settings:'Paramètres'};
function ensureUserBackButtons(){
 $$('.page').forEach(page=>{
  if(page.id==='home'||page.querySelector('.smart-page-back')||page.querySelector('.subhead'))return;
  const bar=document.createElement('div');bar.className='smart-page-back';
  const button=document.createElement('button');button.type='button';button.className='smart-back-button';button.innerHTML='<span aria-hidden="true">←</span> Retour';button.setAttribute('aria-label','Revenir à la rubrique précédente');button.addEventListener('click',goBack);
  const title=document.createElement('strong');title.textContent=smilePageTitles[page.id]||page.querySelector('h2')?.textContent||'SMILE';
  bar.append(button,title);page.insertBefore(bar,page.firstChild);
 });
}
function tab(id,opts={}){if(!id)return;if(!opts.fromPop&&id!==smileCurrentTab){smileTabStack.push(smileCurrentTab);history.pushState({smileTab:id},'',`#${encodeURIComponent(id)}`)}smileCurrentTab=id;if(id==="publications")loadPublications();if(id==="rewards")loadIAProducts();if(id==="vip")renderVIP();$$(".page").forEach(x=>x.classList.toggle("active",x.id===id));$$(".bottom button").forEach(x=>x.classList.toggle("selected",x.dataset.tab===id));ensureUserBackButtons();window.scrollTo({top:0,behavior:'smooth'})}
function goBack(){if(history.state?.smileTab&&history.state.smileTab!== 'home'){history.back();return}if(smileTabStack.length){const previous=smileTabStack.pop();tab(previous,{fromPop:true})}else tab('home',{fromPop:true})}
history.replaceState({smileTab:smileCurrentTab},'',location.pathname+location.search+(location.hash||''));
window.addEventListener('popstate',event=>{const target=event.state?.smileTab||smileTabStack.pop()||'home';const idx=smileTabStack.lastIndexOf(target);if(idx>=0)smileTabStack.splice(idx);tab(target,{fromPop:true})});
