let chosenAvatar="👤";
async function loadMyProducts(){const host=$("#my-products-list");if(!host)return;try{const r=await fetch('/api/my-products',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Impossible de charger vos produits.');host.innerHTML=d.products.length?d.products.map(p=>{const activation=p.activation_at?new Date(p.activation_at):null,upcoming=activation&&activation>Date.now();return `<article class="history-item"><div class="history-top"><strong>${escapeIA(p.name||p.code||'Produit SMILE')}</strong><span>${p.status==='released'?'Terminé':(upcoming?'Réservé — activation à venir':'Activé')}</span></div><div class="history-amount">${Number(p.amount_cfa).toLocaleString('fr-FR')} FCFA</div><small>Durée : ${escapeIA(p.duration_label||'—')} · ${upcoming?'Activation prévue le':'Activé le'} ${new Date(activation||p.approved_at||p.created_at).toLocaleString('fr-FR')}</small><small>Échéance prévue : ${new Date(p.due_at).toLocaleDateString('fr-FR')} · Valeur prévue : ${Number(p.display_value_cfa||p.total_return_cfa||0).toLocaleString('fr-FR')} FCFA</small></article>`}).join(''):'<p class="muted">Vous n’avez pas encore acheté de produit.</p>'}catch(e){host.textContent=e.message}}
async function loadDepositHistory(){const host=$("#deposit-history");if(!host)return;try{const r=await fetch('/api/deposits',{credentials:'same-origin'});if(!r.ok)throw new Error();const d=await r.json();host.innerHTML='<h3>Mes demandes récentes</h3>'+ (d.deposits.length?d.deposits.map(x=>`<p>${Number(x.amount_cfa).toLocaleString('fr-FR')} FCFA · ${x.provider==='tmoney'?'Mixx (TMoney)':String(x.provider).toUpperCase()} · ${x.status==='pending'?'En attente':x.status==='approved'?'Validé':'Rejeté'}</p>`).join(''):'<p>Aucun dépôt pour le moment.</p>')}catch{host.textContent='Connectez-vous pour consulter vos demandes.'}}

async function loadFinancialHistory(){const host=$("#financial-history");if(!host)return;try{const r=await fetch('/api/financial-history',{credentials:'same-origin'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Historique indisponible');const labels={deposit:'Dépôt',withdrawal:'Retrait',investment:'Investissement',commission:'Commission reçue'};const states={pending:'En attente',approved:'Validé',rejected:'Rejeté',paid:'Payé',released:'Terminé',credited:'Crédité'};host.innerHTML=d.transactions.length?d.transactions.map(x=>`<article class="history-item"><div class="history-top"><strong>${labels[x.type]||'Opération'}</strong><span>${states[x.status]||x.status}</span></div><div class="history-amount">${Number(x.amount_cfa).toLocaleString('fr-FR')} FCFA</div><small>${new Date(x.created_at).toLocaleString('fr-FR')} · ${escapeIA(String(x.method||'').toUpperCase())}</small>${x.type==='investment'&&x.offer_name?`<small>Conditions conservées : ${escapeIA(x.offer_name)} · ${escapeIA(x.duration_label||'—')} · montant ${Number(x.offer_min_amount||x.amount_cfa).toLocaleString('fr-FR')} FCFA · total prévu ${Number(x.offer_display_value||x.amount_cfa).toLocaleString('fr-FR')} FCFA</small>`:''}${x.type==='withdrawal'?`<small>Frais : ${Number(x.fee_cfa).toLocaleString('fr-FR')} FCFA · Net : ${Number(x.net_amount_cfa).toLocaleString('fr-FR')} FCFA</small>`:''}${x.reference?`<small>Référence : ${String(x.reference).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</small>`:''}</article>`).join(''):'<p class="muted">Aucune transaction enregistrée.</p>'}catch(e){host.textContent=e.message==='Connexion requise.'?'Connectez-vous pour consulter votre historique.':e.message}}
async function showNotifications(){try{const r=await fetch('/api/notifications',{credentials:'same-origin'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Notifications indisponibles');const html=d.notifications.length?d.notifications.map(n=>`<article class="history-item"><div class="history-top"><strong>${String(n.title).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</strong><small>${new Date(n.created_at).toLocaleString('fr-FR')}</small></div><p>${String(n.message).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</p></article>`).join(''):'<p class="muted">Aucune notification pour le moment.</p>';modal('Mes notifications',html)}catch(e){modal('Mes notifications',`<p class="muted">${e.message}</p>`)}}
function action(a){
 if(a==="settings"){tab("settings");return}
 if(a==="profile"){
  modal("Photo de profil améliorée",`<div style="background:#08224e;color:white;text-align:center;padding:24px;margin:-22px -22px 18px"><div style="font-size:42px">${chosenAvatar}</div><small>Photo actuelle</small></div><p>Changer la photo de profil</p><div class="avatar-grid">${["👨🏽","👩🏾","👨🏿","👩🏽","👨🏻‍🦱","👩🏻‍🦱","🧑🏽","👨🏾‍🦱","👩🏿","👨🏻"].map((v,i)=>`<button class="avatar-choice ${v===chosenAvatar?'active':''}" data-avatar="${v}">${v}</button>`).join("")}</div>`);return
 }
 if(a==="password"){
  modal("Modifier le mot de passe",`<form id="secure-form" class="form-screen"><label>Mot de passe actuel</label><input name="currentPassword" type="password" autocomplete="current-password" required><label>Nouveau mot de passe (6 caractères minimum)</label><input name="newPassword" type="password" minlength="6" autocomplete="new-password" required><label>Confirmer le nouveau mot de passe</label><input name="confirmPassword" type="password" minlength="6" autocomplete="new-password" required><button class="primary" type="submit">Modifier le mot de passe</button><p id="secure-status" class="muted" role="status"></p></form>`);
  $("#secure-form").onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,status=$("#secure-status"),data=Object.fromEntries(new FormData(f));status.textContent='Modification en cours…';try{const r=await fetch('/api/auth/change-password',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(!r.ok)throw new Error(d.error||'Modification impossible');status.textContent=d.message||'Mot de passe modifié.';f.reset()}catch(err){status.textContent=err.message}};return
 }
 if(a==="deposit"){modal("Demande de dépôt manuel",`<form id="manual-deposit-form" class="form-screen"><p class="muted">Effectuez le transfert vers le numéro de réception SMILE affiché ci-dessous. Votre portefeuille sera crédité uniquement après vérification et validation manuelle par l’administrateur.</p><label>Montant (FCFA)</label><input name="amount" type="number" min="500" step="1" required><label>Opérateur</label><select name="provider"><option value="flooz">Flooz</option><option value="tmoney">Mixx (TMoney)</option></select><p id="deposit-destination" class="history-item" role="status">Chargement du numéro de réception…</p><label>Numéro ayant envoyé l’argent</label><input name="phone" type="tel" required minlength="8" maxlength="20" placeholder="+228…"><label>Référence de la transaction</label><input name="reference" required minlength="3" maxlength="120"><button class="primary" type="submit" disabled>Soumettre ma demande</button><p id="manual-deposit-status" class="muted" role="status"></p></form>`);(async()=>{const f=$('#manual-deposit-form'),sel=f.elements.provider,dest=$('#deposit-destination'),submit=f.querySelector('button');let destinations=[];const showDestination=()=>{const x=destinations.find(v=>v.provider===sel.value&&v.enabled&&v.phone);dest.textContent=x?'Numéro officiel de réception '+(x.provider==='tmoney'?'Mixx (TMoney)':'Flooz')+' : '+x.phone:'Aucun numéro actif pour cet opérateur. Choisissez l’autre opérateur ou contactez SMILE.';submit.disabled=!x};try{const r=await fetch('/api/deposit-destinations',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Configuration indisponible');destinations=d.destinations||[];showDestination()}catch(err){dest.textContent=err.message;submit.disabled=true}sel.addEventListener('change',showDestination);f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button'),status=$('#manual-deposit-status');b.disabled=true;try{const r=await fetch('/api/deposits',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),d=await r.json();if(!r.ok)throw new Error(d.error||'Demande impossible');status.textContent='Demande enregistrée. Elle sera vérifiée manuellement avant tout crédit.';f.reset();loadDepositHistory()}catch(err){status.textContent=err.message}finally{showDestination()}}})();return}
 if(a==="withdraw"){modal("Demande de retrait manuel",`<form id="manual-withdraw-form" class="form-screen"><p class="muted">L’administrateur vérifiera votre demande, effectuera le transfert manuellement puis enregistrera la confirmation du paiement. Des conditions d’éligibilité s’appliquent.</p><label>Montant à retirer (FCFA)</label><input name="amount" type="number" min="500" step="1" required><label>Opérateur de réception</label><select name="provider"><option value="flooz">Flooz</option><option value="tmoney">Mixx (TMoney)</option></select><label>Numéro de réception</label><input name="destination" type="tel" required minlength="8" maxlength="20" placeholder="+228…"><label>PIN de retrait (6 chiffres)</label><input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required><button class="primary" type="submit">Soumettre ma demande</button><p id="manual-withdraw-status" class="muted" role="status"></p></form>`);$('#manual-withdraw-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),status=$('#manual-withdraw-status');b.disabled=true;try{const payload=Object.fromEntries(new FormData(f));const r=await fetch('/api/withdrawals',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok&&d.code==='WALLET_REQUIRED'){sessionStorage.setItem('smile_pending_withdrawal',JSON.stringify(payload));modal('Créer votre portefeuille',`<p>Ajoutez un bénéficiaire dans Paramètres → Lier le portefeuille. Vos informations de retrait sont conservées.</p><button class="primary" type="button" id="go-create-wallet">Créer mon portefeuille</button>`);$('#go-create-wallet').onclick=()=>{$('#modal').classList.remove('show');tab('settings')};return}if(!r.ok)throw new Error(d.error||'Demande impossible');status.textContent='Demande enregistrée. Le montant est réservé en attendant le traitement manuel.';f.reset();loadFinancialHistory()}catch(err){status.textContent=err.message}finally{b.disabled=false}};return}
 if(a==="history"){modal("Historique financier",`<div id="financial-history" class="financial-history"><p class="muted">Chargement de votre historique…</p></div>`);loadFinancialHistory();return}
 if(a==="my-products"){modal("Mes produits",`<div id="my-products-list" class="financial-history"><p class="muted">Chargement de vos produits…</p></div>`);loadMyProducts();return}
 if(a==="logout"){(async()=>{try{await fetch('/api/auth/logout?space=user',{method:'POST',credentials:'same-origin'});location.reload()}catch{toast('Impossible de fermer la session. Réessayez.')}})();return}
 if(a==="support"){modal("Service client",`<div class="form-screen"><div id="support-thread"><p class="muted">Chargement de vos échanges…</p></div><form id="support-form"><label>Votre message</label><textarea name="message" required maxlength="3000" placeholder="Décrivez votre demande…"></textarea><button class="primary" type="submit">Envoyer au service client</button><p id="support-user-status" class="muted" role="status"></p></form></div>`);loadUserSupport();$('#support-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,body=f.elements.message.value.trim();if(!body)return;try{const r=await fetch('/api/support/messages',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:body})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Envoi impossible');f.reset();$('#support-user-status').textContent='Message envoyé au service client.';loadUserSupport()}catch(err){$('#support-user-status').textContent=err.message}};return}
 if(a==="pin"){
  modal("PIN sécurisé de retrait",`<form id="pin-form" class="form-screen"><p class="muted">Choisissez un code personnel de 6 chiffres. Il sera stocké sous forme dérivée sécurisée, jamais en clair.</p><label>PIN actuel (si déjà configuré)</label><input name="currentPin" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6"><label>Nouveau PIN à 6 chiffres</label><input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required><button class="primary" type="submit">Enregistrer le PIN</button><p id="pin-status" class="muted" role="status"></p></form>`);
  $('#pin-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));try{const r=await fetch('/api/security/withdrawal-pin',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),v=await r.json();if(!r.ok)throw new Error(v.error||'Enregistrement impossible');$('#pin-status').textContent=v.message;f.reset()}catch(err){$('#pin-status').textContent=err.message}};return
 }
 if(a==="wallet"){
  modal("Mes bénéficiaires Mobile Money",`<form id="beneficiary-form" class="form-screen"><label>Nom du bénéficiaire</label><input name="label" required minlength="2" maxlength="60"><label>Opérateur</label><select name="provider"><option value="flooz">Flooz</option><option value="tmoney">Mixx (TMoney)</option></select><label>Numéro Mobile Money</label><input name="phone" required maxlength="20" placeholder="+228…"><button class="primary" type="submit">Ajouter le bénéficiaire</button><p id="beneficiary-status" class="muted" role="status"></p></form><div id="beneficiary-list" class="form-screen">Chargement…</div>`);
  const load=async()=>{const host=$('#beneficiary-list');try{const r=await fetch('/api/wallet/beneficiaries',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error);host.innerHTML=d.beneficiaries.length?d.beneficiaries.map(x=>`<article class="history-item"><strong>${escapeIA(x.label)}</strong><p>${x.provider==='tmoney'?'Mixx (TMoney)':String(x.provider).toUpperCase()} · ${escapeIA(x.phone)}</p><button class="outline" data-remove-beneficiary="${Number(x.id)}">Supprimer</button></article>`).join(''):'<p class="muted">Aucun bénéficiaire enregistré.</p>'}catch(err){host.textContent=err.message}};
  $('#beneficiary-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,status=$('#beneficiary-status');try{const r=await fetch('/api/wallet/beneficiaries',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),d=await r.json();if(!r.ok)throw new Error(d.error);status.textContent='Bénéficiaire ajouté.';f.reset();load();const pending=sessionStorage.getItem('smile_pending_withdrawal');if(pending){sessionStorage.removeItem('smile_pending_withdrawal');let saved={};try{saved=JSON.parse(pending)}catch{};modal('Reprendre votre retrait',`<p>Votre portefeuille est créé. Retrouvez vos informations et confirmez votre demande.</p><button class="primary" type="button" id="resume-withdrawal">Reprendre le retrait</button>`);$('#resume-withdrawal').onclick=()=>{action('withdraw');const wf=$('#manual-withdraw-form');if(wf)Object.entries(saved).forEach(([k,v])=>{if(wf.elements[k])wf.elements[k].value=v})}}}catch(err){status.textContent=err.message}};
  $('#beneficiary-list').onclick=async e=>{const b=e.target.closest('[data-remove-beneficiary]');if(!b)return;try{const r=await fetch('/api/wallet/beneficiaries/'+b.dataset.removeBeneficiary,{method:'DELETE',credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error);load()}catch(err){toast(err.message)}};load();return
 }
 if(a==="download"){modal("Télécharger l'APP","<p class='muted'>La version installable sera préparée lors de la publication.</p>");return}
 modal("Information","<p class='muted'>Cette fonction sera configurée lors du raccordement sécurisé au serveur.</p>")
}
async function loadPublications(){const host=$('#publications');if(!host)return;try{const r=await fetch('/api/publications',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Publications indisponibles');const old=host.querySelector('.publication-feed');const feed=document.createElement('div');feed.className='publication-feed';feed.innerHTML=d.publications.length?d.publications.map(p=>`<article class="notice-card"><h3>${escapeIA(p.title)}</h3><p>${escapeIA(p.body).replace(/\n/g,'<br>')}</p><small>${new Date(p.published_at).toLocaleString('fr-FR')}</small></article>`).join(''):'<article class="empty"><div class="empty-icon">▤</div><h3>Aucune publication</h3><p>Les actualités publiées par SMILE apparaîtront ici.</p></article>';if(old)old.replaceWith(feed);else host.append(feed)}catch(e){const feed=host.querySelector('.publication-feed')||document.createElement('p');feed.className='publication-feed muted';feed.textContent=e.message;if(!feed.parentNode)host.append(feed)}}
async function loadUserSupport(){const host=$('#support-thread');if(!host)return;try{const r=await fetch('/api/support/messages',{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Messages indisponibles');host.innerHTML='';if(!d.messages.length){host.textContent='Aucun échange pour le moment.';return}for(const m of d.messages){const el=document.createElement('article');el.className='history-item';const who=document.createElement('strong'),body=document.createElement('p'),date=document.createElement('small');who.textContent=m.sender_role==='admin'?'Service client SMILE':'Vous';body.textContent=m.body;date.textContent=new Date(m.created_at).toLocaleString('fr-FR');el.append(who,body,date);host.append(el)}}catch(e){host.textContent=e.message}}

// Conditions officielles affichées avant toute souscription SUPER CRYPTO.
const SUPER_CRYPTO_CONDITIONS={
1:{personal:30000,clients:5,team:100000,scope:'subordonnés directs de niveau 1',extra:'Une période probatoire de 7 jours est requise pour obtenir le statut VIP2 et continuer à percevoir son salaire.'},
2:{personal:60000,clients:8,team:285000,scope:'subordonnés directs de niveau 1',extra:'Au moins 1 membre de l’équipe doit avoir atteint VIP1 ou un niveau supérieur.'},
3:{personal:140000,clients:15,team:600000,scope:'subordonnés directs de niveau 1',extra:'Au moins 3 membres de l’équipe doivent être VIP1 ou plus.'},
4:{personal:300000,clients:30,team:1400000,scope:'subordonnés directs de niveau 1',extra:'Au moins 5 membres de l’équipe doivent être VIP1 ou plus.'},
5:{personal:600000,clients:100,team:4900000,scope:'niveaux 1, 2 et 3'},
6:{personal:780000,clients:200,team:9800000,scope:'niveaux 1, 2 et 3'},
7:{personal:1200000,clients:500,team:28000000,scope:'niveaux 1, 2 et 3'},
8:{personal:1900000,clients:1000,team:50000000,scope:'niveaux 1, 2 et 3'},
9:{personal:2900000,clients:3000,team:60000000,scope:'niveaux 1, 2 et 3'},
10:{personal:4600000,clients:6000,team:60000000,scope:'niveaux 1, 2 et 3'}
};
function superCryptoVipNumber(offer){
 const name=String(offer?.name||'');
 const m=name.match(/(?:FZ)?VIP\s*([1-9]|10)(?:\.0)?/i);
 return m?Number(m[1]):null;
}
function superCryptoConditionsHtml(level){
 const c=SUPER_CRYPTO_CONDITIONS[level];
 if(!c)return '';
 return `<div class="form-screen"><p>Avant de poursuivre, vérifiez les conditions d’accès au <strong>VIP${level}</strong> :</p>
 <p>Recharge personnelle valide : <strong>${c.personal.toLocaleString('fr-FR')} XOF</strong></p>
 <p>Nombre de clients / recharges valides (${c.scope}) : <strong>${c.clients.toLocaleString('fr-FR')} personnes</strong></p>
 <p>Recharge totale des subordonnés (${c.scope}) : <strong>${c.team.toLocaleString('fr-FR')} XOF</strong></p>
 ${c.extra?`<p>${escapeIA(c.extra)}</p>`:''}
 <p class="muted">La souscription ne doit être poursuivie que si ces conditions sont remplies et vérifiables.</p>
 <button class="primary" type="button" id="confirm-vip-conditions">CONFIRMER</button></div>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-invest-offer]');
 if(!b||b.disabled||b.dataset.vipConditionsConfirmed==='1'||iaCategory!=='super')return;
 const offerId=Number(b.dataset.investOffer),offer=iaOffers.find(x=>Number(x.id)===offerId);
 const level=superCryptoVipNumber(offer);
 if(!level||!SUPER_CRYPTO_CONDITIONS[level])return;
 e.preventDefault();e.stopImmediatePropagation();
 modal(`Conditions d’accès — VIP${level}`,superCryptoConditionsHtml(level));
 const confirm=$('#confirm-vip-conditions');
 if(confirm)confirm.onclick=()=>{b.dataset.vipConditionsConfirmed='1';$('#modal').classList.remove('show');b.click();};
},true);

document.addEventListener("click",async e=>{const b=e.target.closest('[data-invest-offer]');if(!b||b.disabled)return;const offerId=Number(b.dataset.investOffer);b.disabled=true;try{const [offersRes,balanceRes]=await Promise.all([fetch('/api/offers',{credentials:'same-origin'}),fetch('/api/wallet/balance',{credentials:'same-origin'})]);const offersData=await offersRes.json(),wallet=await balanceRes.json();if(!offersRes.ok||!balanceRes.ok)throw new Error(wallet.error||offersData.error||'Impossible de vérifier votre solde.');const offer=offersData.offers.find(x=>Number(x.id)===offerId);if(!offer)throw new Error('Offre indisponible.');const isLimited=offer.category==='limited';const choices=isLimited?(Array.isArray(offer.reservation_amounts_cfa)?offer.reservation_amounts_cfa.map(Number):[]):[Number(offer.min_amount_cfa)];if(!choices.length)throw new Error('Aucun montant de réservation n’est configuré pour ce produit.');let amount=choices[0];const available=Number(wallet.available_cfa);const idempotencyKey=crypto.randomUUID();const beforeLaunch=isLimited&&offer.sale_start_at&&new Date(offer.sale_start_at)>new Date();const fmtDate=v=>v?new Date(v).toLocaleString('fr-FR',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';const optionsHtml=choices.map((v,i)=>`<button type="button" class="reservation-choice ${i===0?'selected':''}" data-reservation-choice="${v}">${v.toLocaleString('fr-FR')}</button>`).join('');modal(isLimited?(beforeLaunch?'Réserver à l’avance':'Souscrire au produit'):'Confirmer l’achat',`${isLimited?`<form id="investment-form" class="form-screen reservation-form"><h3 class="reservation-heading">${beforeLaunch?'Réserver à l’avance':'Détails de souscription'}</h3><div class="reservation-row"><span>Nom du produit</span><strong>${escapeIA(offer.name)}</strong></div><div class="reservation-row"><span>Vente débute</span><strong>${fmtDate(offer.sale_start_at)}</strong></div><div class="reservation-row"><span>Vente se termine</span><strong>${fmtDate(offer.sale_end_at)}</strong></div><label>Montant réservé</label><div class="reservation-choices">${optionsHtml}</div><div class="reservation-row"><span>Solde du portefeuille produit</span><strong>${Number(offer.product_wallet_balance_cfa||0).toLocaleString('fr-FR')} XOF</strong></div><div class="reservation-row"><span>Réservations restantes</span><strong>${Number(offer.reservations_remaining||0)}</strong></div><p class="reservation-row"><span>Votre solde disponible</span><strong>${available.toLocaleString('fr-FR')} XOF</strong></p><p class="reservation-row"><span>Montant à payer</span><strong id="limited-final-amount">${amount.toLocaleString('fr-FR')} XOF</strong></p><p class="muted">La réservation correspond au paiement intégral du produit. Aucune annulation ni aucun remboursement après confirmation.</p><div class="reservation-form-actions"><button class="secondary reservation-back" type="button" data-reservation-back>Retour</button><button class="primary" type="submit">${beforeLaunch?'Confirmer la réservation':'Confirmer la souscription'}</button></div></form>`:`<form id="investment-form" class="form-screen"><p>Produit : <strong>${escapeIA(offer.name)}</strong></p><p>Solde disponible : <strong>${available.toLocaleString('fr-FR')} F CFA</strong></p><p>Montant à débiter : <strong>${amount.toLocaleString('fr-FR')} F CFA</strong></p><button class="primary" type="submit">Confirmer mon achat</button></form>`}`);const amountSelect=$('#investment-form .reservation-choices');if(amountSelect){amountSelect.addEventListener('click',ev=>{const choice=ev.target.closest('[data-reservation-choice]');if(!choice)return;amount=Number(choice.dataset.reservationChoice);amountSelect.querySelectorAll('.reservation-choice').forEach(x=>x.classList.toggle('selected',x===choice));$('#limited-final-amount').textContent=amount.toLocaleString('fr-FR')+' XOF'})}const form=$('#investment-form');form.onsubmit=async ev=>{ev.preventDefault();const submit=form.querySelector('button[type="submit"]');if(submit.disabled)return;submit.disabled=true;submit.textContent='Traitement sécurisé…';if(available<amount){submit.disabled=false;submit.textContent=isLimited?(beforeLaunch?'Payer et réserver':'Payer et souscrire'):'Confirmer mon achat';toast('Solde disponible insuffisant pour le montant sélectionné.');return}try{const r=await fetch('/api/investments',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({offerId,amount,idempotencyKey})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Achat impossible');$('#modal').classList.remove('show');toast(d.idempotentReplay?'Opération déjà confirmée : aucun second débit.':(isLimited?(beforeLaunch?'Réservation payée. Activation à la mise en ligne.':'Souscription payée et confirmée.'):'Achat confirmé : produit activé dans votre compte.'));renderProducts();loadIAProducts();const bal=await fetch('/api/wallet/balance',{credentials:'same-origin'});if(bal.ok){const bd=await bal.json();$('#subscription').textContent=Number(bd.available_cfa||0).toLocaleString('fr-FR')+' F'}modal(isLimited?(beforeLaunch?'Réservation confirmée':'Souscription confirmée'):'Achat confirmé',`<div class="financial-history"><p><strong>${escapeIA(d.offer||offer.name)}</strong> ${isLimited?(beforeLaunch?'est réservé et intégralement payé. Il sera activé à la mise en ligne.':'est maintenant souscrit et payé.'):'est maintenant activé dans votre compte.'}</p><p>Montant débité : <strong>${amount.toLocaleString('fr-FR')} FCFA</strong></p><p>Consultez-le à tout moment dans la rubrique « Mes produits ».</p><button class="primary" type="button" id="view-my-products">Voir mes produits</button></div>`);$('#view-my-products').onclick=()=>{modal('Mes produits',`<div id="my-products-list" class="financial-history"><p class="muted">Chargement…</p></div>`);loadMyProducts()};}catch(err){submit.disabled=false;submit.textContent='Réessayer';toast(err.message)}}}catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener("click",e=>{const b=e.target.closest("[data-avatar]");if(b){chosenAvatar=b.dataset.avatar;const main=document.querySelector("#main-avatar");if(main)main.textContent=chosenAvatar;const old=document.querySelector(".avatar-grid");if(old){old.querySelectorAll("button").forEach(x=>x.classList.toggle("active",x.dataset.avatar===chosenAvatar));const current=document.querySelector(".dialog div[style*='background:#08224e'] div");if(current)current.textContent=chosenAvatar}}});

document.addEventListener("click",e=>{const t=e.target.closest("[data-tab]");if(t)tab(t.dataset.tab);const a=e.target.closest("[data-action]");if(a)action(a.dataset.action)});
$("#notice")?.addEventListener("click",showNotifications);
$("#close").onclick=()=>$("#modal").classList.remove("show");$("#modal").onclick=e=>{if(e.target.id==="modal")$("#modal").classList.remove("show")};
$("#copy").onclick=async()=>{try{await navigator.clipboard.writeText($("#invite").value);toast("Lien copié")}catch{toast("Copiez le lien manuellement")}};
$('#create-post')?.remove();
renderProducts();
ensureUserBackButtons();

// Authentification utilisateur : pas de création silencieuse de comptes invités.
let authMode='login';
function setAuthMode(mode){authMode=mode;const login=mode==='login';$('#user-login-form').hidden=!login;$('#user-register-form').hidden=login;$('#auth-title').textContent=login?'Bienvenue':'Créer un compte';$('#auth-description').textContent=login?'Connectez-vous à votre compte SMILE.':'Inscrivez-vous pour accéder à votre espace personnel.';$('#auth-switch').textContent=login?'Créer un compte':'J’ai déjà un compte';$('#auth-error').textContent=''}
function syncRegistrationReferral(){const field=$('#register-ref');if(!field)return;const linked=new URLSearchParams(location.search).get('ref');const hint=$('#register-ref-hint');if(linked){field.value=linked;field.readOnly=true;field.setAttribute('aria-readonly','true');field.title='Code fourni par le lien d’invitation : non modifiable';if(hint)hint.textContent='Code reçu par lien d’invitation — non modifiable.';}else{field.readOnly=false;field.removeAttribute('aria-readonly');if(hint)hint.textContent='Vous pouvez saisir un code ou laisser ce champ vide.';}}
syncRegistrationReferral();
$('#auth-switch')?.addEventListener('click',()=>setAuthMode(authMode==='login'?'register':'login'));
async function submitUserAuth(form,endpoint){const error=$('#auth-error'),button=form.querySelector('button[type="submit"]');error.textContent='';button.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(endpoint.includes('/login')){data.login=data.login||'';}if(endpoint.endsWith('/register')){const linked=new URLSearchParams(location.search).get('ref');data.ref=linked||String(data.ref||'').trim();}const r=await fetch(endpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let d={};try{d=await r.json()}catch{throw new Error('Réponse invalide du serveur. Vérifiez que le serveur SMILE fonctionne.')}if(!r.ok)throw new Error(d.error||`Impossible de ${endpoint.endsWith('/register')?'créer le compte':'se connecter'} (erreur ${r.status}).`);if(d.user?.role!=='user')throw new Error('Cet accès est réservé aux comptes utilisateurs. Utilisez le lien administrateur si vous gérez SMILE.');$('#auth-gate').hidden=true;form.reset();await loadAccount(d.user)}catch(e){error.textContent=e.message}finally{button.disabled=false}}
$('#user-login-form')?.addEventListener('submit',e=>{e.preventDefault();submitUserAuth(e.currentTarget,'/api/auth/login?space=user')});
$('#user-register-form')?.addEventListener('submit',e=>{e.preventDefault();submitUserAuth(e.currentTarget,'/api/auth/register')});
async function loadAccount(user){if(!user)return;$('#username').textContent=user.name||'Utilisateur SMILE';$('#user-id').textContent=user.public_id||'—';renderProducts();loadIAProducts();const [balanceResult,teamResult]=await Promise.allSettled([fetch('/api/wallet/balance',{credentials:'same-origin'}),fetch('/api/team',{credentials:'same-origin'})]);renderVIP();if(balanceResult.status==='fulfilled'&&balanceResult.value.ok){const b=await balanceResult.value.json();$('#subscription').textContent=Number(b.available_cfa||0).toLocaleString('fr-FR')+' F';}if(teamResult.status==='fulfilled'&&teamResult.value.ok){const t=await teamResult.value.json();$('#invite').value=t.referralLink||'';const counts={1:0,2:0,3:0};(t.levels||[]).forEach(x=>counts[x.level]=Number(x.members)||0);const cards=$('#team .stats')?.children;if(cards?.length>=4){cards[0].querySelector('strong').textContent=counts[1]+counts[2]+counts[3];cards[1].querySelector('strong').textContent=counts[1];cards[2].querySelector('strong').textContent=counts[2];cards[3].querySelector('strong').textContent=counts[3]}const members=$('#team-members');if(members){members.innerHTML=(t.members||[]).length?(t.members||[]).map(m=>`<div class="team-member"><strong>${escapeIA(m.name)}</strong><span>Niveau ${Number(m.level)} · ${escapeIA(m.public_id)}</span></div>`).join(''):'<p class="muted">Aucun membre pour le moment.</p>'}}}
async function initializeSession(){
 try{
  const r=await fetch('/api/auth/me?space=user',{credentials:'same-origin'}); const d=await r.json();
  if(!r.ok) throw new Error(d.error||'Session indisponible');
  if(d.user?.role==='user'){ $('#auth-gate').hidden=true; await loadAccount(d.user); }
  else {$('#auth-gate').hidden=false;setAuthMode('login');}
 }catch(e){
  console.error('Initialisation SMILE :',e);
  $('#auth-gate').hidden=false;$('#auth-error').textContent='Impossible de joindre le serveur. Vérifiez la connexion et réessayez.';
 }
}
initializeSession();

// Actualisation automatique des quotas après une modification administrative.
// Les offres sont relues lorsque le membre revient sur l’onglet, puis toutes les 30 secondes
// tant que le compte est connecté et que la page est visible.
let quotaRefreshRunning=false;
async function refreshVisibleQuotas(){
 if(quotaRefreshRunning||document.visibilityState==='hidden'||$('#auth-gate')?.hidden!==true)return;
 quotaRefreshRunning=true;
 try{await Promise.all([renderProducts(),loadIAProducts()]);}
 finally{quotaRefreshRunning=false;}
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshVisibleQuotas()});
window.addEventListener('focus',refreshVisibleQuotas);
setInterval(refreshVisibleQuotas,30000);
